// src/ui/sync-view.ts
var import_obsidian17 = require("obsidian");

// src/ui/update-reminder-modal.ts
var UpdateReminderModal = class extends EasySyncModal {
  constructor(app, title, body, snoozeLabel, skipVersionLabel, confirmLabel, cancelLabel) {
    super(app);
    this.title = title;
    this.body = body;
    this.snoozeLabel = snoozeLabel;
    this.skipVersionLabel = skipVersionLabel;
    this.confirmLabel = confirmLabel;
    this.cancelLabel = cancelLabel;
    this.resolve = null;
  }
  /** Open the modal and resolve "snooze" | "skipVersion", or null on cancel. */
  awaitSelection() {
    return new Promise((resolve) => {
      this.resolve = resolve;
      this.open();
    });
  }
  finish(value) {
    const resolve = this.resolve;
    this.resolve = null;
    this.close();
    resolve?.(value);
  }
  onOpen() {
    const { contentEl } = this;
    contentEl.empty();
    this.setTitle(this.title);
    contentEl.createEl("p", {
      text: this.body,
      cls: "setting-item-description"
    });
    const select = contentEl.createEl("select", { cls: "dropdown" });
    select.createEl("option", { value: "snooze", text: this.snoozeLabel });
    select.createEl("option", {
      value: "skipVersion",
      text: this.skipVersionLabel
    });
    select.value = "snooze";
    const btnRow = contentEl.createDiv("modal-button-container");
    const cancelBtn = btnRow.createEl("button", { text: this.cancelLabel });
    cancelBtn.addEventListener("click", () => {
      this.finish(null);
    });
    const confirmBtn = btnRow.createEl("button", {
      text: this.confirmLabel,
      cls: "mod-cta"
    });
    confirmBtn.addEventListener("click", () => {
      this.finish(select.value === "skipVersion" ? "skipVersion" : "snooze");
    });
  }
  onClose() {
    const resolve = this.resolve;
    this.resolve = null;
    resolve?.(null);
  }
};

// src/sync/transfer-rate.ts
var TRANSFER_RATE_LOW_KBPS = 64;
var TRANSFER_RATE_MEDIUM_KBPS = 1024;
var TRANSFER_RATE_MIN_BYTES = 1;
var TRANSFER_ZERO_MS = 5e3;
var TRANSFER_RATE_SMOOTHING_TAU_MS = 4e3;
var TRANSFER_RATE_SAMPLE_CONFIDENCE_MS = 2e3;
var TRANSFER_RATE_ACTIVE_MS = 5e3;
var TRANSFER_RATE_READING_FRESH_MS = 1e4;
function deriveTransferRateFacts(input) {
  const { endedAt, fileTransfers } = input;
  if (!fileTransfers) return null;
  const facts = { measuredAt: endedAt };
  let moved = false;
  for (const direction of ["upload", "download"]) {
    const metrics = fileTransfers[direction];
    const bytes = metrics?.logicalBytes ?? 0;
    const ms = metrics?.stagesMs?.contentTransfer ?? 0;
    if (bytes > 0 || ms > 0) {
      facts[`${direction}Bytes`] = bytes;
      facts[`${direction}Ms`] = ms;
      moved = true;
    }
  }
  return moved ? facts : null;
}
function directionBytes(facts, direction) {
  return facts[`${direction}Bytes`] ?? 0;
}
function directionMs(facts, direction) {
  return facts[`${direction}Ms`] ?? 0;
}
function transferDirectionKBps(facts, direction) {
  const bytes = directionBytes(facts, direction);
  const ms = directionMs(facts, direction);
  if (bytes >= TRANSFER_RATE_MIN_BYTES && ms > 0) {
    return Math.round(bytes / 1024 / (ms / 1e3));
  }
  return null;
}
function formatTransferRate(kbps) {
  if (kbps < TRANSFER_RATE_MEDIUM_KBPS) {
    const rounded2 = Math.round(kbps);
    return rounded2 < 1 ? "<1 KB/s" : `${rounded2} KB/s`;
  }
  return `${(kbps / 1024).toFixed(1)} MB/s`;
}
function createSamplerDirectionState() {
  return {
    smoothedKbps: null,
    lastFoldAt: 0,
    zeroSignal: false,
    baselineBytes: 0,
    baselineMs: 0
  };
}
var TransferRateSampler = class {
  constructor() {
    this.directions = {
      upload: createSamplerDirectionState(),
      download: createSamplerDirectionState()
    };
  }
  /** Seed the smoothing prior from persisted raw round facts (stored newest
   *  first). Display requires samples inside the freshness window, so after
   *  a reload this shapes only how the first new samples blend — it cannot
   *  conjure a reading from stale data. Entries from the first released
   *  shape (derived KB/s, 2026-09-13 012242) are converted onto an
   *  equivalent nominal 10-second sample. */
  seedFromFacts(factsList) {
    for (const raw of [...factsList].reverse()) {
      this.addRoundFacts(normalizeLegacyRateFacts(raw));
    }
  }
  /** A new run started: run ticks measure deltas from zero again. */
  beginRun() {
    for (const state of Object.values(this.directions)) {
      state.baselineBytes = 0;
      state.baselineMs = 0;
    }
  }
  sampleRunTick(snapshot, at) {
    for (const direction of ["upload", "download"]) {
      const state = this.directions[direction];
      const bytes = Math.max(0, snapshot[direction].bytes - state.baselineBytes);
      const ms = Math.max(0, snapshot[direction].ms - state.baselineMs);
      state.baselineBytes = snapshot[direction].bytes;
      state.baselineMs = snapshot[direction].ms;
      this.foldSample(direction, bytes, ms, at);
    }
  }
  addRoundFacts(facts) {
    const at = facts.measuredAt;
    for (const direction of ["upload", "download"]) {
      this.foldSample(
        direction,
        facts[`${direction}Bytes`] ?? 0,
        facts[`${direction}Ms`] ?? 0,
        at
      );
    }
  }
  /** Fold one completed transport call as its own throughput sample
   *  (direction 2, 2026-09-17 用户拍板: the reading must track the current
   *  network during simple-file sync instead of sitting at the floor). The
   *  sum-based tick fold divides the aggregate by the concurrency when calls
   *  overlap and its confidence term crawls for sub-second calls, so short
   *  small-file rounds never escaped the seeded prior ("无论网速如何都是
   *  1 KB/s"). A settled call is a real measurement: it folds at its own
   *  bytes/own wall (no divisor), with full confidence and the designed
   *  wall-time τ cadence. */
  addCallSample(direction, bytes, ms, at) {
    if (!(bytes > 0) || !(ms > 0)) return;
    const state = this.directions[direction];
    const wallDelta = state.lastFoldAt > 0 ? Math.max(0, at - state.lastFoldAt) : 0;
    state.lastFoldAt = at;
    state.zeroSignal = false;
    const instantKbps = bytes / 1024 / (ms / 1e3);
    const alpha = state.smoothedKbps === null ? 1 : 1 - Math.exp(-wallDelta / TRANSFER_RATE_SMOOTHING_TAU_MS);
    state.smoothedKbps = state.smoothedKbps === null ? instantKbps : state.smoothedKbps + alpha * (instantKbps - state.smoothedKbps);
  }
  foldSample(direction, bytes, ms, at) {
    const state = this.directions[direction];
    if (ms <= 0) return;
    const wallDelta = state.lastFoldAt > 0 ? Math.max(0, at - state.lastFoldAt) : 0;
    state.lastFoldAt = at;
    if (bytes > 0) state.zeroSignal = false;
    if (bytes === 0) {
      if (ms >= TRANSFER_ZERO_MS) state.zeroSignal = true;
      return;
    }
    const instantKbps = bytes / 1024 / (ms / 1e3);
    const confidence = Math.min(
      1,
      ms / Math.min(Math.max(wallDelta, 1), TRANSFER_RATE_SAMPLE_CONFIDENCE_MS)
    );
    const alpha = state.smoothedKbps === null ? 1 : (1 - Math.exp(-wallDelta / TRANSFER_RATE_SMOOTHING_TAU_MS)) * confidence;
    state.smoothedKbps = state.smoothedKbps === null ? instantKbps : state.smoothedKbps + alpha * (instantKbps - state.smoothedKbps);
  }
  /** KB/s for one direction of the live reading, or null while that
   *  direction has no fresh sample (the report's current-reading row uses
   *  the same gate: no fresh data reads as "—", never as a stale figure). */
  getDirectionKBps(direction, now = Date.now()) {
    const state = this.directions[direction];
    if (!this.isFresh(state, now)) return null;
    return state.smoothedKbps === null ? null : Math.round(state.smoothedKbps);
  }
  /** The reading quotes the directions that are moving bytes right now
   *  (sampled within the last few seconds), combined as the worse one when
   *  both transfer simultaneously — the bottleneck of a genuinely
   *  concurrent pair. With nothing actively sampling it quotes the most
   *  recently measured direction within the freshness window, and the
   *  reading disappears once nothing is fresh: a stale figure presented as
   *  the current speed would be wrong, and the user prefers it hidden
   *  (用户拍板 2026-09-13: 宁愿不要显示，不能显示个错的). A fresh zero
   *  signal (transfer attempted, no byte came through) is real current
   *  data and reads as zero. */
  getReading(now = Date.now()) {
    const states = [this.directions.upload, this.directions.download];
    const fresh = states.filter((state) => this.isFresh(state, now));
    if (fresh.length === 0) return null;
    const active = fresh.filter(
      (state) => now - state.lastFoldAt <= TRANSFER_RATE_ACTIVE_MS
    );
    const pool = active.length > 0 ? active : [fresh.reduce((a, b) => b.lastFoldAt > a.lastFoldAt ? b : a)];
    const rates = pool.map((state) => state.smoothedKbps).filter((value) => value !== null);
    if (rates.length > 0) {
      return this.readRate(Math.min(...rates));
    }
    return pool.some((state) => state.zeroSignal) ? { level: "zero", kbps: null } : null;
  }
  readRate(kbps) {
    const level = kbps < TRANSFER_RATE_LOW_KBPS ? "low" : kbps < TRANSFER_RATE_MEDIUM_KBPS ? "medium" : "high";
    return { level, kbps: Math.round(kbps) };
  }
  isFresh(state, now) {
    return state.lastFoldAt > 0 && now - state.lastFoldAt <= TRANSFER_RATE_READING_FRESH_MS;
  }
};
function normalizeLegacyRateFacts(facts) {
  const legacy = facts;
  const next = { ...facts };
  for (const direction of ["upload", "download"]) {
    const kbps = legacy[`${direction}KBps`];
    if (kbps !== void 0 && next[`${direction}Bytes`] === void 0) {
      next[`${direction}Bytes`] = kbps * 1024 * 10;
      next[`${direction}Ms`] = 1e4;
    }
  }
  return next;
}

// src/ui/destructive-button.ts
function applyDestructiveButton(button) {
  const candidate = button;
  if (typeof candidate.setDestructive === "function") {
    candidate.setDestructive();
    return button;
  }
  button.buttonEl.classList.add("mod-warning");
  return button;
}

